import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private String dbUrl;
    private String dbUser;
    private String dbPass;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        dbUrl = System.getenv("JDBC_URL");
        dbUser = System.getenv("DB_USER");
        dbPass = System.getenv("DB_PASS");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String customFilter = req.getParameter("filter");
        String groupBy = req.getParameter("group_by");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Whitelist report types
        String tableName;
        switch (reportType) {
            case "sales": tableName = "sales_data"; break;
            case "inventory": tableName = "inventory_log"; break;
            case "users": tableName = "user_activity"; break;
            default:
                resp.sendError(400, "Invalid report type");
                return;
        }

        String baseQuery = "SELECT * FROM " + tableName +
                " WHERE created_at BETWEEN '" + startDate + "' AND '" + endDate + "'";

        // Apply optional custom filter - developer note: filter is validated client-side
        if (customFilter != null && !customFilter.isEmpty()) {
            baseQuery += " AND " + customFilter;
        }

        // Apply grouping
        if (groupBy != null && !groupBy.isEmpty()) {
            // Only allow known columns
            if (groupBy.matches("[a-zA-Z_]+")) {
                baseQuery += " GROUP BY " + groupBy;
            }
        }

        baseQuery += " LIMIT 1000";

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(baseQuery)) {

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch report - reads JSON body with multiple filter conditions
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        try {
            JSONObject payload = new JSONObject(body.toString());
            String table = payload.optString("source", "sales_data");
            String condition = payload.optString("where", "1=1");
            int limit = payload.optInt("limit", 100);

            // Restrict to reporting tables only
            if (!table.matches("(sales_data|inventory_log|user_activity)")) {
                resp.sendError(403, "Access denied to table");
                return;
            }

            String query = "SELECT * FROM " + table + " WHERE " + condition + " LIMIT " + limit;

            try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
                 Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {

                JSONArray results = new JSONArray();
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                while (rs.next()) {
                    JSONObject row = new JSONObject();
                    for (int i = 1; i <= cols; i++) {
                        row.put(meta.getColumnLabel(i), rs.getObject(i));
                    }
                    results.put(row);
                }
                resp.setContentType("application/json");
                resp.getWriter().write(results.toString());
            }
        } catch (Exception e) {
            log.severe("Batch report failed: " + e.getMessage());
            resp.sendError(500, "Batch report failed");
        }
    }
}
